75	/**
76	 * Reports whether an anonymous visitor to a private instance should be redirected
77	 * to the sign-in page for the given path.
78	 *
79	 * A private instance (no configured instance URL) hides everything from anonymous
80	 * visitors except share-link pages, which stay accessible so public shares keep
81	 * working. Authenticated visitors and open instances are never gated.
82	 */
83	export function shouldGatePrivateInstance(params: { isPrivateInstance: boolean; isAuthenticated: boolean; pathname: string }): boolean {
84	  const { isPrivateInstance, isAuthenticated, pathname } = params;
85	  if (!isPrivateInstance || isAuthenticated) {
86	    return false;
87	  }
88	  return !pathname.startsWith(`${ROUTES.SHARED_MEMO}/`);
